{
  "a_sentences": [
    {
      "a_text": "Der Streitgegenstand betrifft die Frage, ob die Vorinstanz Bundesrecht verletzt hat, indem sie einen Anspruch des Beschwerdeführers auf eine Lebenspartnerrente zulasten der Profond Vorsorgeeinrichtung verneinte (P1).",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Die Begünstigung von Personen nach Art. 20a Abs. 1 BVG gehört zur weitergehenden beruflichen Vorsorge, wobei die Vorsorgeeinrichtungen frei bestimmen können, ob und für welche Personen sie Hinterlassenenleistungen vorsehen (P2, P6).",
      "b_propositions": ["P2", "P6"]
    },
    {
      "a_text": "Die Vorsorgeeinrichtungen dürfen die Ausrichtung von Leistungen nach Art. 20a BVG von einer vorgängigen schriftlichen Begünstigtenerklärung abhängig machen, da dies kein reiner Formalismus, sondern ein Instrument zur Klärung ist (P3, P4).",
      "b_propositions": ["P3", "P4"]
    },
    {
      "a_text": "Im Gegensatz zu den obligatorischen Hinterlassenenansprüchen hat die versicherte Person bei einer Lebensgemeinschaft die Wahl, ob sie den Lebenspartner begünstigen will (P5).",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Die kumulativen Voraussetzungen des Vertrauensschutzes sind nicht erfüllt, da der Vorsorgeausweis keine vorbehaltlose Zusicherung einer Lebenspartnerrente ohne schriftliche Begünstigtenerklärung darstellt (P7, P8).",
      "b_propositions": ["P7", "P8"]
    }
  ]
}
